package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class LocaleUtils_toLocale_TriageGen5Test {

    @Test
    public void testToLocale_Null() {
        assertNull(LocaleUtils.toLocale(null));
    }

    @Test
    public void testToLocale_TooShort() {
        try {
            LocaleUtils.toLocale("a");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: a", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidCaseLanguage() {
        // First char not lowercase
        try {
            LocaleUtils.toLocale("En");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: En", e.getMessage());
        }
        // Second char not lowercase
        try {
            LocaleUtils.toLocale("eN");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: eN", e.getMessage());
        }
    }

    @Test
    public void testToLocale_ValidLanguageOnly() {
        Locale expected = new Locale("en");
        assertEquals(expected, LocaleUtils.toLocale("en"));
    }

    @Test
    public void testToLocale_InvalidLengthAfterLanguage() {
        // Length 3 or 4 is invalid if not exactly 2
        try {
            LocaleUtils.toLocale("en_");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_", e.getMessage());
        }
        try {
            LocaleUtils.toLocale("en_a");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_a", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidSeparator() {
        try {
            LocaleUtils.toLocale("en-US");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en-US", e.getMessage());
        }
    }

    @Test
    public void testToLocale_ValidLanguageAndVariantWithUnderscore() {
        // Handles the ch3 == '_' branch: len > 2, len < 5 is caught above, 
        // so we need a specific pattern for the ch3 == '_' check logic
        // The code says: if (ch3 == '_') return new Locale(str.substring(0, 2), "", str.substring(4));
        // This requires len >= 5 (since substring(4) is called).
        // Example: "en__US" -> len 6. ch3 is '_'.
        Locale expected = new Locale("en", "", "US");
        assertEquals(expected, LocaleUtils.toLocale("en__US"));
    }

    @Test
    public void testToLocale_InvalidCountryCase() {
        // ch3 or ch4 not uppercase
        try {
            LocaleUtils.toLocale("en_us");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_us", e.getMessage());
        }
        try {
            LocaleUtils.toLocale("en_uS");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_uS", e.getMessage());
        }
    }

    @Test
    public void testToLocale_ValidLanguageAndCountry() {
        Locale expected = new Locale("en", "US");
        assertEquals(expected, LocaleUtils.toLocale("en_US"));
    }

    @Test
    public void testToLocale_InvalidLengthForVariant() {
        // len < 7 check
        try {
            LocaleUtils.toLocale("en_US_");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_US_", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidThirdSeparator() {
        try {
            LocaleUtils.toLocale("en_US-x");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_US-x", e.getMessage());
        }
    }

    @Test
    public void testToLocale_ValidLanguageCountryVariant() {
        Locale expected = new Locale("en", "US", "X");
        assertEquals(expected, LocaleUtils.toLocale("en_US_X"));
    }
}
